INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d4a2c6462e0d7fe3d0e2','AMEDEX 2025 OPTHA _ ENT 1-38.pdf','110','Ophthalmology/ENT','F
>
A 26-year-old woman has presented with a red
right eye since this morning. For the past few
hours, she also has had mild discomfort and
irritation of the eye. She denies any discharge
or itchiness. On examination, eye movements,
orbital pressure and visual acuity are normal.
The cornea shows no abnormality and has
preserved light and red reflexes. A funduscopic
exam reveals no retinal abnormality either. She
has unaffected visual acuity. The sclera is red,
as shown in the following photograph. Which of
