INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ae1d1d62cc2753249ed2','AMEDEX 2025 Orthopaedic  (1).pdf','61','Orthopaedics/Rheumatology','Anthony, a 40-year-old man, presented with a
10-day history of a worsening rash that began
on his legs and advanced to his lower
abdomen. The rash was red and nonpruritic.
The patient also had muscle aches, mild
abdominal discomfort, and a recent sore throat.
His medical history included diabetes mellitus,
hypertension, and cirrhosis due to nonalcoholic
steatohepatitis. His long-term medications were
insulin degludec, semaglutide, and lisinopril.
Physical examination revealed a nontender,
symmetrical, petechial, and purpuric rash from
the soles of the feet to the lower abdomen. His
physical examination was otherwise
unremarkable, including normal vital signs. His
platelet count was low at 100 x 10° per uL (110
x 10° per L), but findings on a complete blood
count and basic metabolic panel were otherwise
normal. Urinalysis revealed 10 to 25 red blood
cells per high-power field without protein.
Recent laboratory tests were negative for
hepatitis. Based on the patient''s history and
physical examination findings, which one of the
following is the most likely diagnosis?','{"A":"ANCA-associated vasculltis.","B":"Cryoglobulinemia vasculitis.","C":"Drug-induced leukocytoclastic\nvasculitis.","D":"Immune thrombocytopenic purpura.","E":"Immunoglobulin A (IgA) vasculitis."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","supporting_pages":[61,62],"source_qid":null,"duplicate_group_id":"exact-72962d409bc3","duplicate_sources":[{"record_id":"ae1d1d62cc2753249ed2","record_type":"text_mcq","source_file":"AMEDEX 2025 Orthopaedic  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","source_page":61,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"ae1d1d62cc2753249ed2","source_file":"AMEDEX 2025 Orthopaedic  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","source_year":2025,"source_page":61,"supporting_pages":[61,62],"source_qid":null,"domain_hint":"Orthopaedics/Rheumatology","stem":"Anthony, a 40-year-old man, presented with a\n10-day history of a worsening rash that began\non his legs and advanced to his lower\nabdomen. The rash was red and nonpruritic.\nThe patient also had muscle aches, mild\nabdominal discomfort, and a recent sore throat.\nHis medical history included diabetes mellitus,\nhypertension, and cirrhosis due to nonalcoholic\nsteatohepatitis. His long-term medications were\ninsulin degludec, semaglutide, and lisinopril.\nPhysical examination revealed a nontender,\nsymmetrical, petechial, and purpuric rash from\nthe soles of the feet to the lower abdomen. His\nphysical examination was otherwise\nunremarkable, including normal vital signs. His\nplatelet count was low at 100 x 10° per uL (110\nx 10° per L), but findings on a complete blood\nc