INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b7575b7d6c710427805f','AMEDEX 2025 Orthopaedic  (1).pdf','89','Orthopaedics/Rheumatology','A 35-year-old woman is brought to the
Emergency Department after she sustained a
motor vehicle accident as a frontseat
passenger, and had her left ankle injured. On
examination, her vital signs are stable. The
left ankle joint is laterally displaced and there
is a 13-cm laceration over the joint. The left
dorsal pedis pulse is barely felt and the foot is
cold and pale. The condition is diagnosed as
open fracture/dislocation of the ankle joint.
Which one of the following is the most
important step in preventing wound infection
and ensuing complications?','{"A":"Intravenous antibiotics.","B":"Wound debridment.","C":"Tetanus prophylaxis.","D":"Reduction of the displacement.","E":"X-ray of the joint."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-35ed9fc9ee84","duplicate_sources":[{"record_id":"b7575b7d6c710427805f","record_type":"text_mcq","source_file":"AMEDEX 2025 Orthopaedic  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","source_page":89,"source_qid":null},{"record_id":"1342ef597f5557a53285","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1131,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"b7575b7d6c710427805f","source_file":"AMEDEX 2025 Orthopaedic  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","source_year":2025,"source_page":89,"source_qid":null,"domain_hint":"Orthopaedics/Rheumatology","stem":"A 35-year-old woman is brought to the\nEmergency Department after she sustained a\nmotor vehicle accident as a frontseat\npassenger, and had her left ankle injured. On\nexamination, her vital signs are stable. The\nleft ankle joint is laterally displaced and there\nis a 13-cm laceration over the joint. The left\ndorsal pedis pulse is barely felt and the foot is\ncold and pale. The condition is diagnosed as\nopen fracture/dislocation of the ankle joint.\nWhich one of the following is the most\nimportant step in preventing wound infection\nand ensuing complications?","options":{"A":"Intravenous antibiotics.","B":"Wound debridment.","C":"Tetanus prophylaxis.","D":"Reduction of the displ