INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7790ea0a6ddcd423d9c9','AMEDEX 2025 Orthopaedic  (1).pdf','94','Orthopaedics/Rheumatology','While getting off the car, a 40-year-old man
developed sudden-onset severe low back pain
and got locked in the middle of the way,
according to him. He is now in the emergency
department for evaluation, complaining of lower
back pain, shooting sharp pain in the right leg
and foot, and restricted and painful lumbar
movements. He runs a grocery store and has
