INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d5b70742ec3ce5ad4247','AMEDEX 2025 Orthopaedic  (1).pdf','162','Orthopaedics/Rheumatology','A 73-year-old woman presents to your practice
with a complaint of shoulder pain for the past
8 months. The pain is mostly felt in both
shoulders and is aching and vague in nature.
she also has shoulder girdle stiffness in the
morning, often taking 30-60 minutes of physical
activity and sometimes a hot bath to improve.
She denies any fever, weight loss, headache, or
visual symptoms. Past medical history is
significant for osteoporosis, for which she is on
alendronate and supplemental calcium and
vitamin D. Laboratory tests show normocytic,
normochromic anemia and an erythrocyte
sedimentation rate (ESR) of 100mm/h. Which
one of the following is the most appropriate next
step in management?','{"A":"Corticosteroids.","B":"Non-steroidal anti-inflammatory\ndrugs (NSAIDs).","C":"eS Paracetamol.","D":"Methotrexate.","E":"Infliximab."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-03c34f804d12","duplicate_sources":[{"record_id":"d5b70742ec3ce5ad4247","record_type":"text_mcq","source_file":"AMEDEX 2025 Orthopaedic  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","source_page":162,"source_qid":null},{"record_id":"4ab9d3e19d3fd91d6dad","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1154,"source_qid":"1141"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"d5b70742ec3ce5ad4247","source_file":"AMEDEX 2025 Orthopaedic  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","source_year":2025,"source_page":162,"source_qid":null,"domain_hint":"Orthopaedics/Rheumatology","stem":"A 73-year-old woman presents to your practice\nwith a complaint of shoulder pain for the past\n8 months. The pain is mostly felt in both\nshoulders and is aching and vague in nature.\nshe also has shoulder girdle stiffness in the\nmorning, often taking 30-60 minutes of physical\nactivity and sometimes a hot bath to improve.\nShe denies any fever, weight loss, headache, or\nvisual symptoms. Past medical history is\nsignificant for osteoporosis, for which she is on\nalendronate and supplemental calcium and\nvitamin D. Laboratory tests show normocytic,\nnormochromic anemia and an erythrocyte\nsedimentation rate (ESR) of 100mm/h. Which\none of the following is the most appropriate next\nstep in