INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('24a6fca5d7be8ad70dde','AMEDEX 2025 Orthopaedic  (1).pdf','185','Orthopaedics/Rheumatology','Ot Size. _F . :
A 67-year-old woman presents to your clinic
with complaints of painful hips and shoulders
and headache. She relates that muscle pain is
felt in both arms and hips. She feels her
Shoulders are stiff and her hips cannot move
when she wakes up. It almost takes 40
minutes of painful physical activity for the
stiffness to relent. Her appetite is decreased
and she has lost 5 kg. “To make me even
more miserable, the terrible headaches have
just been started”, she mentions. The
headache is felt on the right side and is
throbbing with no response to analgesics. On
physical examination, she is noted to have
bilateral painful restricted movements of
Shoulder and hip joints. Her right temple is
tender to touch. She is not febrile and the
rest of the exam is inconclusive. Which one of
the following would be the most appropriate
next step in management?','{"A":"Check serum creatine kinase (CK)","B":"level.","C":"Check the rheumatoid factor.","D":"Check ESR.","E":"Perfor erttTastre aio psy."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-9671e4ef731a","duplicate_sources":[{"record_id":"24a6fca5d7be8ad70dde","record_type":"text_mcq","source_file":"AMEDEX 2025 Orthopaedic  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","source_page":185,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"24a6fca5d7be8ad70dde","source_file":"AMEDEX 2025 Orthopaedic  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (1).pdf","source_year":2025,"source_page":185,"source_qid":null,"domain_hint":"Orthopaedics/Rheumatology","stem":"Ot Size. _F . :\nA 67-year-old woman presents to your clinic\nwith complaints of painful hips and shoulders\nand headache. She relates that muscle pain is\nfelt in both arms and hips. She feels her\nShoulders are stiff and her hips cannot move\nwhen she wakes up. It almost takes 40\nminutes of painful physical activity for the\nstiffness to relent. Her appetite is decreased\nand she has lost 5 kg. “To make me even\nmore miserable, the terrible headaches have\njust been started”, she mentions. The\nheadache is felt on the right side and is\nthrobbing with no response to analgesics. On\nphysical examination, she is noted to have\nbilateral painful restricted movements of\nShoulder and hip joints. Her right temple is\ntender to touch. She is not febrile and the\nrest of the exam is inconclusive. Which one of\nthe following would be the most appropriate\nnext step in manageme