INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f3fe22b9948dfe667ea4','AMEDEX 2025 Orthopaedic  (2).pdf','1','Orthopaedics/Rheumatology','Sue, 56 years old, presents to the Emergency
Department with acute-onset right Knee pain
Starting 3 hours ago and worsening gradually.
On examination, she has a BMI of 32, blood
pressure of 158/105 mmHg, pulse rate of 90
bpm, and temperature of 37°C. A joint aspirate
excludes septic arthritis; however, the presence
of birefringent crystals is highly suggestive of
gouty arthritis. Her medical history is
remarkable for chronic kidney disease due to
long-standing hypertension. Laboratory tests
are ordered, of which a serum uric acid of 0.6
mmol/L (normal: 0.12-0.42 mmol/L) and a GFR
of 30 (normal: 90-120 ml/min/1 73m*) are
remarkable. Which one of the following is the
most appropriate treatment to consider for her?','{"A":"Paracetamol.","B":"Naproxen.","C":"Codeine.","D":"Colchicine.","E":"Allopurinol. ©"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-28a8b1347f21","duplicate_sources":[{"record_id":"f3fe22b9948dfe667ea4","record_type":"text_mcq","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_page":1,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"f3fe22b9948dfe667ea4","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_year":2025,"source_page":1,"source_qid":null,"domain_hint":"Orthopaedics/Rheumatology","stem":"Sue, 56 years old, presents to the Emergency\nDepartment with acute-onset right Knee pain\nStarting 3 hours ago and worsening gradually.\nOn examination, she has a BMI of 32, blood\npressure of 158/105 mmHg, pulse rate of 90\nbpm, and temperature of 37°C. A joint aspirate\nexcludes septic arthritis; however, the presence\nof birefringent crystals is highly suggestive of\ngouty arthritis. Her medical history is\nremarkable for chronic kidney disease due to\nlong-standing hypertension. Laboratory tests\nare ordered, of which a serum uric acid of 0.6\nmmol/L (normal: 0.12-0.42 mmol/L) and a GFR\nof 30 (normal: 90-120 ml/min/1 73m*) are\nremarkable. Which one of the following is the\nmost appropriate treatment to consider for her?","options":{"A":"Paracetamol.","B":"Naproxen.","C":"Codeine.","D":"Colchicine.","E":"Allopurinol. ©"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","cu