INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('791c1ab42e8d9c4efba2','AMEDEX 2025 Orthopaedic  (2).pdf','64','Orthopaedics/Rheumatology','The 9-year-old Tim is brought to the Emergency
Department by his mum after he fell off his bike
and hurt his left shoulder. The left shoulder is
painful, and he is barely moving his left arm due
to the pain. On physical examination, there is no
bruise or deformity of the left shoulder, but there
is tenderness over the middle third of the left
clavicle. Neurovascular examination of the left
arm and hand is normal. Which one of the
following is the most appropriate next step for
investigation?','{"A":"X-ray of the left clavicle; PA view.","B":"X-ray of the left clavicle; AP view.","C":"X-ray of both clavicles; AP view.","D":"CT scan.","E":"X-ray of the left clavicle; oblique view."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-c7963d3c602c","duplicate_sources":[{"record_id":"791c1ab42e8d9c4efba2","record_type":"text_mcq","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_page":64,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"791c1ab42e8d9c4efba2","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_year":2025,"source_page":64,"source_qid":null,"domain_hint":"Orthopaedics/Rheumatology","stem":"The 9-year-old Tim is brought to the Emergency\nDepartment by his mum after he fell off his bike\nand hurt his left shoulder. The left shoulder is\npainful, and he is barely moving his left arm due\nto the pain. On physical examination, there is no\nbruise or deformity of the left shoulder, but there\nis tenderness over the middle third of the left\nclavicle. Neurovascular examination of the left\narm and hand is normal. Which one of the\nfollowing is the most appropriate next step for\ninvestigation?","options":{"A":"X-ray of the left clavicle; PA view.","B":"X-ray of the left clavicle; AP view.","C":"X-ray of both clavicles; AP view.","D":"CT scan.","E":"X-ray of the left clavicle; oblique view."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification",